  const actor = await requireCapability("expansion.manage"), id = uuid(input.versionId)
  if (!publicationEnabled()) throw new ProfileError("Public profile publication is not enabled. Approved profiles stay private until it is.", 403)
export async function getProfilesAdmin() {
  const actor = await requireCapability("expansion.manage")
  return db.transaction(async (tx) => {
    await tx.execute(sql`set transaction isolation level repeatable read`)
    await founderGuard(tx, actor)
    const versions = await rows(tx, sql`select v.id,v.version,v.status,u.display_name partner_name,v.display_name,v.biography,v.operating_area,v.enquiry_mode,v.consent_at,v.consent_version,v.review_note,v.submitted_at from expansion_profile_versions v join expansion_partners p on p.id=v.partner_id j
    const publications = await rows(tx, sql`select pub.id,pub.slug,pub.status,pub.published_at,pub.end_reason,pub.achievements,u.display_name partner_name from expansion_profile_publications pub join expansion_partners p on p.id=pub.partner_id join admin_users u on u.id=p.user_id order by pub.publis
    return { versions, publications, publicationEnabled: publicationEnabled() }
  })
}

