    const c = await runAs(founderA, () => createContentItem({ kind: "knowledge", slug: `kb-race-${suffix}`, audience: "client_facing", cadence: "service", title: "Race entry", fields: knowledge(), sourceRefs: ["faq:hosting-provided"] }))
